function fourDivisorSum(nums: number[]): number {
  let total = 0;
  for (const x of nums) {
    let count = 0, sum = 0;
    for (let d = 1; d <= x; d++) if (x % d === 0) { count++; sum += d; }
    if (count === 4) total += sum;
  }
  return total;
}

