function fourDivisorSum(nums: number[]): number {
  let total = 0;
  for (const x of nums) {
    let count = 0, sum = 0;
    for (let d = 1; d * d <= x && count <= 4; d++) {
      if (x % d !== 0) continue;
      const e = x / d;
      count++; sum += d;
      if (e !== d) { count++; sum += e; } // a square root is its own partner
    }
    if (count === 4) total += sum;
  }
  return total;
}

